import collections, hashlib, json, os, pathlib, statistics, subprocess
root = pathlib.Path.cwd()
work = root / '_build/typeenv2387/compare'
profile_root = root / '_build/typeenv2387/profiles'
profile_root.mkdir()
env = {k: v for k, v in os.environ.items() if not k.startswith(('VIBE_', 'NODE_'))}
env.update(VIBE_PREOPEN_DIR=str(root), VIBE_IMPORT_ABI='raw', VIBE_FS_COMPILE='1', VIBE_BACKEND='wasi', VIBE_RC='1', VIBE_CHECKED_MODULE_CACHE='off', VIBE_EXPERIMENTAL_AST_CACHE='0', VIBE_CODEGEN_BODY_CACHE='off', VIBE_WASM_NAMES='0')
expected = json.loads((work / 'results.json').read_text())['runs'][0]['output_sha256']
report = {'protocol': 'Three alternating AB/BA cold profiles per runtime, fresh cache for every profile. Separate from uninstrumented timing runs. Same CLI source, RC output, flags and compiler artifacts as compare.py.', 'runs': [], 'harness': pathlib.Path(__file__).read_text()}
for runtime in ['bump', 'rc']:
    for iteration in range(3):
        for side in ('ab' if iteration % 2 == 0 else 'ba'):
            folder = profile_root / f'{runtime}-{iteration}-{side}'
            folder.mkdir()
            flags = '\n'.join(['--cpu-prof', f'--cpu-prof-dir={folder}', '--cpu-prof-name=cold.cpuprofile'])
            proc = subprocess.run(['bash', 'scripts/run_wasm_vibe_host_runner.sh', '--invoke', 'cli_main', str(work / f'{side}-{runtime}.wasm'), 'lib/@vibe/cli/entry.vibe', str(folder / 'out.wasm'), 'cli_main'], env={**env, 'VIBE_BUILD_CACHE_DIR': str(folder / 'cache'), 'VIBE_NODE_EXTRA_FLAGS': flags}, capture_output=True, text=True, timeout=300)
            (folder / 'cold.log').write_text(proc.stdout + proc.stderr)
            proc.check_returncode()
            digest = hashlib.sha256((folder / 'out.wasm').read_bytes()).hexdigest()
            assert digest == expected, (runtime, side, digest, expected)
            p = json.loads((folder / 'cold.cpuprofile').read_text())
            nodes = {n['id']: n for n in p['nodes']}
            parent = {c: n['id'] for n in p['nodes'] for c in n.get('children', [])}
            own = collections.Counter()
            costs = collections.Counter()
            for sid, dt in zip(p['samples'], p['timeDeltas']):
                name = nodes[sid]['callFrame']['functionName'] or '(anon)'
                own[name] += dt
                chain = []
                while sid in nodes:
                    chain.append(nodes[sid]['callFrame']['functionName'] or '(anon)')
                    sid = parent.get(sid)
                lookup = any(fn.startswith('env_lookup_binding') for fn in chain)
                if lookup:
                    costs['lookup_inclusive_ms'] += dt
                    if name.startswith('hash_string_'):
                        costs['lookup_hash_ms'] += dt
                    if name.startswith('bsearch_leftmost_') or name.startswith('str_lt_') or name == '__rt_str_eq':
                        costs['lookup_string_compare_ms'] += dt
                if any(fn.startswith('env_bind_with_origin_') for fn in chain):
                    costs['bind_inclusive_ms'] += dt
                if any(fn.startswith('env_cache_') for fn in chain):
                    costs['env_cache_inclusive_ms'] += dt
                if any(fn.startswith('env_name_index_new_') for fn in chain):
                    costs['index_build_inclusive_ms'] += dt
                if any(fn.startswith('env_name_index_find_') for fn in chain):
                    costs['index_find_inclusive_ms'] += dt
            row = {'runtime': runtime, 'round': iteration, 'variant': side, 'temperature': 'cold', 'output_sha256': digest, 'sampled_ms': sum(own.values()) / 1000, **{k: v / 1000 for k, v in costs.items()}, 'self_ms': {k: v / 1000 for k, v in own.most_common(60)}}
            report['runs'].append(row)
            (profile_root / 'results.json').write_text(json.dumps(report, indent=2) + '\n')
            print(json.dumps({k: v for k, v in row.items() if k != 'self_ms'}), flush=True)
report['medians'] = []
for runtime in ['bump', 'rc']:
    for side in 'ab':
        rs = [r for r in report['runs'] if r['runtime'] == runtime and r['variant'] == side]
        report['medians'].append({'runtime': runtime, 'variant': side, **{k: statistics.median(r.get(k, 0) for r in rs) for k in ['sampled_ms', 'lookup_inclusive_ms', 'lookup_hash_ms', 'lookup_string_compare_ms', 'bind_inclusive_ms', 'env_cache_inclusive_ms', 'index_build_inclusive_ms', 'index_find_inclusive_ms']}})
(profile_root / 'results.json').write_text(json.dumps(report, indent=2) + '\n')
print(json.dumps(report['medians']), flush=True)
